import sys

def has_duplicate_parentheses(expression):
    stack = []
    for char in expression:
        if char == ')':
            if not stack:
                return True
            has_inner = False
            while stack and stack[-1] != '(':
                stack.pop()
                has_inner = True
            if not stack:
                return True
            stack.pop()
            if not has_inner:
                return True
        else:
            stack.append(char)
    return False

def main():
    expression = sys.stdin.readline().strip()
    if has_duplicate_parentheses(expression):
        print("true")
    else:
        print("false")

if __name__ == "__main__":
    main()
